import org.junit.jupiter.api.Test;

class MemoryShorthandConstructTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P = VF.createIRI("urn:p");
	private static final IRI O = VF.createIRI("urn:o");

	@Test
	void modifierGraphsOnlyFilterAndOrderSolutions() {
		SailRepository repository = new SailRepository(new MemoryStore());
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			IRI first = VF.createIRI("urn:first");
			IRI second = VF.createIRI("urn:second");
			IRI graph = VF.createIRI("urn:g");
			IRI modifier = VF.createIRI("urn:modifier");
			connection.add(first, P, O);
			connection.add(second, P, O);
			connection.add(first, modifier, O, graph);
			connection.add(second, modifier, O, graph);
			Model expected = new LinkedHashModel();
			expected.add(first, P, O);
			expected.add(second, P, O);
			MapBindingSet bindings = new MapBindingSet();
			bindings.addBinding("o", O);

			for (String modifiers : List.of(
					"ORDER BY EXISTS { GRAPH <urn:g> { ?s <urn:modifier> ?o } }",
					"ORDER BY NOT EXISTS { GRAPH <urn:g> { ?s <urn:absent> ?o } }",
					"GROUP BY ?s ?o HAVING (EXISTS { GRAPH <urn:g> { ?s <urn:modifier> ?o } })",
					"ORDER BY EXISTS { { SELECT ?s WHERE { GRAPH <urn:g> { ?s <urn:modifier> <urn:o> } } } }",
					"ORDER BY EXISTS { GRAPH <urn:g> { ?s <urn:modifier> ?o } } VALUES ?o { <urn:o> }")) {
				String shorthand = "CONSTRUCT WHERE { ?s <urn:p> ?o } " + modifiers;
				GraphQuery direct = connection.prepareGraphQuery(shorthand);
				direct.setBinding("o", O);
				assertEquals(expected, evaluate(direct), shorthand);
				assertEquals(expected,
						evaluate(connection.prepareGraphQuery(SPARQLQueries.withInitialBindings(shorthand, bindings))),
						"Serialized initial bindings: " + shorthand);
				assertEquals(expected, evaluate(connection.prepareGraphQuery(
						"CONSTRUCT { ?s <urn:p> ?o } WHERE { ?s <urn:p> ?o } " + modifiers)),
						"Explicit template control: " + modifiers);
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void shorthandTemplateBlankNodesStayFreshAndSharedWithModifiers() {
		SailRepository repository = new SailRepository(new MemoryStore());
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			IRI q = VF.createIRI("urn:q");
			IRI value = VF.createIRI("urn:value");
			for (Resource subject : List.of(VF.createIRI("urn:first"), VF.createBNode("source"))) {
				connection.add(subject, P, O);
				connection.add(subject, q, value);
			}
			String shorthand = "CONSTRUCT WHERE { _:result <urn:p> ?o ; <urn:q> ?value } "
					+ "ORDER BY EXISTS { GRAPH <urn:g> { ?s <urn:modifier> ?o } } "
					+ "VALUES ?o { <urn:o> }";
			Model direct = evaluate(connection.prepareGraphQuery(shorthand));
			assertEquals(4, direct.size());
			Set<BNode> subjects = new HashSet<>();
			for (Statement statement : direct) {
				subjects.add(assertInstanceOf(BNode.class, statement.getSubject()));
			}
			assertEquals(2, subjects.size(), "A fresh template blank node is allocated for each matching solution");
			for (BNode subject : subjects) {
				assertNotEquals(VF.createBNode("source"), subject,
						"Template nodes must be fresh relative to input nodes");
				assertTrue(direct.contains(subject, P, O));
				assertTrue(direct.contains(subject, q, value));
			}
			MapBindingSet bindings = new MapBindingSet();
			bindings.addBinding("o", O);
			Model serialized = evaluate(
					connection.prepareGraphQuery(SPARQLQueries.withInitialBindings(shorthand, bindings)));
			assertTrue(Models.isomorphic(direct, serialized));
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void explicitTemplateLabelsRemainFreshAndSharedInsideNestedTerms() {
		SailRepository repository = new SailRepository(new MemoryStore());
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			BNode input = VF.createBNode("input");
			IRI nested = VF.createIRI("urn:nested");
			var selected = VF.createLiteral("selected");
			connection.add(input, P, selected);
			connection.add(VF.createIRI("urn:named"), P, selected);
			String query = "CONSTRUCT { _:shared <urn:p> ?o ; "
					+ "<urn:nested> <<( _:shared <urn:p> ?o )>> } WHERE { _:shared <urn:p> ?o }";
			GraphQuery prepared = connection.prepareGraphQuery(query);
			prepared.setBinding("o", selected);
			Model direct = evaluate(prepared);
			assertEquals(4, direct.size());
			Set<BNode> subjects = new HashSet<>();
			for (Statement statement : direct) {
				BNode subject = assertInstanceOf(BNode.class, statement.getSubject());
				assertNotEquals(input, subject, "The template label must not refer to the matched input blank node");
				subjects.add(subject);
				if (statement.getPredicate().equals(nested)) {
					TripleTerm term = assertInstanceOf(TripleTerm.class, statement.getObject());
					assertEquals(subject, term.getSubject(), "Nested terms share the enclosing template label");
					assertEquals(selected, term.getObject());
				}
			}
			assertEquals(2, subjects.size(), "Each solution needs a fresh template scope");
			MapBindingSet bindings = new MapBindingSet();
			bindings.addBinding("o", selected);
			Model serialized = evaluate(
					connection.prepareGraphQuery(SPARQLQueries.withInitialBindings(query, bindings)));
			assertTrue(Models.isomorphic(direct, serialized));
		} finally {
			repository.shutDown();
		}
	}

	private static Model evaluate(GraphQuery query) {
		try (GraphQueryResult result = query.evaluate()) {
			Model model = new LinkedHashModel();
			result.forEach(model::add);
			return model;
		}
	}
}
